import React from 'react';

import {
  getAvailableHalves,
  getClosedMonthIndex,
  HALF_MONTH_RANGES,
  HalfKey,
  TimePeriodType,
} from 'utils/timePeriod/timePeriodAvailability';

import { HALVES } from '../../constants';
import { useTimePeriodSliderPreview } from '../../hooks/useTimePeriodSliderPreview';
import {
  BracketBarDiv,
  BracketsWrapperDiv,
  HalfBracketBtn,
  HalfBracketsRow,
  HalfLabelSpan,
  HalfLineDiv,
  HalfTickDiv,
  SliderAreaContainer,
} from '../../TimePeriodSelector.styles';
import { computeSliderPositions, getHalfIndexFromEnd } from '../../utils';
import { StaticMonthLabels } from '../StaticMonthLabels';
import { TimePeriodSliderTrack } from '../TimePeriodSliderTrack';

interface HalfSelectorProps {
  cutoffDate: string;
  selectedEnd: HalfKey | null;
  onEndChange: (end: HalfKey) => void;
}

export function TimePeriodHalfSelector({
  cutoffDate,
  selectedEnd,
  onEndChange,
}: Readonly<HalfSelectorProps>) {
  const closedMonthIndex = getClosedMonthIndex(cutoffDate);
  const available = getAvailableHalves(cutoffDate);
  const positions = computeSliderPositions(
    TimePeriodType.HALF,
    selectedEnd,
    closedMonthIndex,
  );

  const halfIdx = getHalfIndexFromEnd(selectedEnd);
  const selectedHalf = Object.values(HalfKey)[halfIdx];
  const {
    startMonthIndex: selectedStartMonth,
    endMonthIndex: selectedEndMonth,
  } = HALF_MONTH_RANGES[selectedHalf];

  const {
    isDragging,
    previewEnd,
    previewIndex: previewHalfIndex,
    handleDraggingChange,
    handleValueChange,
    handleValueCommit,
  } = useTimePeriodSliderPreview<HalfKey>({
    mapIndexToEnd: (idx) => {
      const halfIdx = Math.max(0, Math.min(1, Math.floor(idx)));
      const h = HALVES[halfIdx];
      return available.includes(h) ? h : null;
    },
    onCommit: onEndChange,
  });

  const previewPositions =
    isDragging && previewEnd !== null
      ? computeSliderPositions(
          TimePeriodType.HALF,
          previewEnd,
          closedMonthIndex,
        )
      : null;

  return (
    <SliderAreaContainer data-testid="time-period-half-selector">
      <TimePeriodSliderTrack
        positions={positions}
        preview={isDragging ? previewPositions : null}
        isDragging={isDragging}
        sliderProps={{
          type: 'slider',
          min: 0,
          max: 1,
          maxInput: 1,
          step: 1,
          value: [isDragging ? (previewHalfIndex ?? halfIdx) : halfIdx],
          callback: handleValueChange,
          onValueCommit: handleValueCommit,
          onDraggingChange: handleDraggingChange,
          thumbAriaLabel: 'Select half year',
        }}
      />

      <StaticMonthLabels
        closedMonthIndex={closedMonthIndex}
        selectedMonthIndexes={[selectedStartMonth, selectedEndMonth]}
      />

      <BracketsWrapperDiv>
        <HalfBracketsRow>
          {HALVES.map((h) => {
            const isEnabled = available.includes(h);
            const isActive = selectedEnd === h;
            const isDimmed = isEnabled && !isActive;

            return (
              <HalfBracketBtn
                key={h}
                data-testid={`half-${h}`}
                type="button"
                disabled={!isEnabled}
                aria-pressed={isActive}
                aria-label={`Select ${h}`}
                onClick={() => isEnabled && onEndChange(h)}
              >
                <BracketBarDiv>
                  <HalfTickDiv
                    $muted={!isEnabled}
                    $dimmed={isDimmed}
                    $active={isActive}
                  />
                  <HalfLineDiv
                    $muted={!isEnabled}
                    $dimmed={isDimmed}
                    $active={isActive}
                  />
                  <HalfTickDiv
                    $muted={!isEnabled}
                    $dimmed={isDimmed}
                    $active={isActive}
                  />
                </BracketBarDiv>
                <HalfLabelSpan
                  $active={isActive}
                  $dimmed={isDimmed}
                  $muted={!isEnabled}
                >
                  {h}
                </HalfLabelSpan>
              </HalfBracketBtn>
            );
          })}
        </HalfBracketsRow>
      </BracketsWrapperDiv>
    </SliderAreaContainer>
  );
}
